<script lang="ts">
 let {draft,assets,selected='',time=0,onselect,onmove}:{draft:any;assets:any[];selected?:string;time?:number;onselect:(id:string,time:number)=>void;onmove:(track:string,id:string,start:number,snap?:boolean)=>void}=$props();
 function drag(event:PointerEvent,track:string,clip:any){if(event.button!==0)return;event.preventDefault();const node=event.currentTarget as HTMLElement,rail=node.parentElement!;const start=event.clientX,width=rail.getBoundingClientRect().width;node.setPointerCapture(event.pointerId);let target=clip.start;
 const move=(e:PointerEvent)=>{target=clip.start+(e.clientX-start)/width*draft.duration;node.style.transform=`translateX(${e.clientX-start}px)`};const end=()=>{node.style.transform='';node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',end);node.removeEventListener('pointercancel',cancel);onmove(track,clip.id,target)};const cancel=()=>{node.style.transform='';node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',end);node.removeEventListener('pointercancel',cancel)};node.addEventListener('pointermove',move);node.addEventListener('pointerup',end);node.addEventListener('pointercancel',cancel)}
</script>
<section aria-label="Editing timeline" class="space-y-3 rounded-lg border border-border p-3"><div class="flex justify-between text-xs text-muted-foreground"><span>Timeline · drag to move, arrow keys to nudge</span><span>{Number(time).toFixed(2)}s</span></div>
 {#each ['clips','audio'] as track}<div><p class="mb-1 text-xs">{track==='clips'?'Visual layers':'Audio tracks'}</p><div class="relative min-h-14 rounded-md bg-muted/40">{#each draft[track] as clip(clip.id)}<button type="button" aria-label={`Select ${track==='clips'?'visual':'audio'} clip ${assets.find(a=>a.id===clip.asset_id)?.name??clip.id}`} aria-pressed={selected===clip.id} class={`absolute top-1 min-h-11 touch-none overflow-hidden rounded-md border px-2 text-left text-xs ${selected===clip.id?'border-foreground bg-accent':'border-border bg-secondary'}`} style={`left:${clip.start/draft.duration*100}%;width:${Math.max(3,clip.duration/draft.duration*100)}%`} onclick={()=>onselect(clip.id,clip.start)} onpointerdown={e=>drag(e,track,clip)} onkeydown={e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();onmove(track,clip.id,clip.start+(e.key==='ArrowLeft'?-1:1)*(e.shiftKey?1:1/draft.fps),false)}}}>{assets.find(a=>a.id===clip.asset_id)?.name??clip.id}</button>{/each}</div></div>{/each}
 <p class="text-xs text-muted-foreground">Changes snap to frames and nearby clip edges. Layer order controls overlaps. Exact timings remain editable below.</p>
</section>
